+        if ordered.iter().enumerate().any(|(np, (_, op))| *op != np) {
+            snap.output = ordered.iter().map(|(_, op)| snap.output.get(*op).cloned().unwrap_or(Value::Null)).collect();
+            self.positions = ordered.iter().enumerate().map(|(np, (w, _))| (*w, np)).collect();
+        }
+    }
