+/// `model_dump(exclude_none=True, mode="json")` of an item, plus the LangChain `index`.
+fn lc_dump(item: &Value, index: i64) -> Value {
+    let mut d = item.clone();
+    strip_nulls(&mut d);
+    if let Value::Object(m) = &mut d {
+        m.insert("index".into(), json!(index));
+    }
+    d
+}
