+        } else if ty == DONE && item_type()? == "custom_tool_call" {
+            let i = self.advance(item_id, attr("output_index")?, None)?;
+            content.push(lc_dump(item.expect("checked"), i));
+            let args = format!("{{\"__arg1\": {}}}", field("input"));
