+        } else if ty == "response.refusal.done" {
+            content.push(json!({"type": "refusal", "refusal": dumped("refusal")}));
+        } else if ty == ADDED && item_type()? == "reasoning" {
+            let i = self.advance(item_id, attr("output_index")?, None)?;
