+    let mut open = with_status(&done, "in_progress");
+    open["input"] = json!("");
+    let evs = vec![
+        added(i, open),
+        scoped("response.custom_tool_call_input.delta", i, id, json!({"delta": input})),
+        scoped("response.custom_tool_call_input.done", i, id, json!({"input": input})),
